class Solution {
public:
    int maxAncestorDiff(TreeNode* root) {
        auto dfs = [](auto& self, TreeNode* node, int cur_min, int cur_max) -> int {
            if (!node) return cur_max - cur_min;
            cur_min = min(cur_min, node->val);
            cur_max = max(cur_max, node->val);
            return max(self(self, node->left, cur_min, cur_max), self(self, node->right, cur_min, cur_max));
        };
        return dfs(dfs, root, root->val, root->val);
    }
};

class Solution {
    public int maxAncestorDiff(TreeNode root) {
        return dfs(root, root.val, root.val);
    }

    private int dfs(TreeNode node, int curMin, int curMax) {
        if (node == null) return curMax - curMin;
        curMin = Math.min(curMin, node.val);
        curMax = Math.max(curMax, node.val);
        return Math.max(dfs(node.left, curMin, curMax), dfs(node.right, curMin, curMax));
    }
}

var maxAncestorDiff = function(root) {
    const dfs = (node, curMin, curMax) => {
        if (!node) return curMax - curMin;
        curMin = Math.min(curMin, node.val);
        curMax = Math.max(curMax, node.val);
        return Math.max(dfs(node.left, curMin, curMax), dfs(node.right, curMin, curMax));
    };
    return dfs(root, root.val, root.val);
